-- Automated test schema only; the application uses MySQL by default.
PRAGMA foreign_keys = ON;
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'admin', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE vehicles (id INTEGER PRIMARY KEY AUTOINCREMENT, registration TEXT NOT NULL UNIQUE COLLATE NOCASE, make TEXT NOT NULL, model TEXT NOT NULL, model_year INTEGER NOT NULL, mileage INTEGER NOT NULL DEFAULT 0, mot_expiry TEXT, insurance_expiry TEXT, next_service_date TEXT, next_service_mileage INTEGER, status TEXT NOT NULL DEFAULT 'Available', archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE drivers (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, licence_number TEXT NOT NULL UNIQUE COLLATE NOCASE, licence_expiry TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE assignments (id INTEGER PRIMARY KEY AUTOINCREMENT, vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE RESTRICT, driver_id INTEGER NOT NULL REFERENCES drivers(id) ON DELETE RESTRICT, started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, ended_at TEXT, active_vehicle_id INTEGER GENERATED ALWAYS AS (CASE WHEN ended_at IS NULL THEN vehicle_id ELSE NULL END) STORED UNIQUE, active_driver_id INTEGER GENERATED ALWAYS AS (CASE WHEN ended_at IS NULL THEN driver_id ELSE NULL END) STORED UNIQUE);
CREATE TABLE maintenance (id INTEGER PRIMARY KEY AUTOINCREMENT, vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE RESTRICT, service_date TEXT NOT NULL, mileage INTEGER NOT NULL, description TEXT NOT NULL, supplier TEXT NOT NULL, cost_pence INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE repairs (id INTEGER PRIMARY KEY AUTOINCREMENT, vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE RESTRICT, repair_date TEXT NOT NULL, description TEXT NOT NULL, supplier TEXT NOT NULL, cost_pence INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE login_attempts (email_key TEXT PRIMARY KEY, failures INTEGER NOT NULL DEFAULT 0, locked_until TEXT);
